-- Dumping structure for table public.user_sessions
DROP TABLE IF EXISTS "user_sessions";
CREATE TABLE IF NOT EXISTS "public"."user_sessions" (
	"id" TEXT NOT NULL,
	"user_id" TEXT NOT NULL,
	"token_hash" TEXT NOT NULL,
	"expires_at" TIMESTAMPTZ NOT NULL,
	"revoked_at" TIMESTAMPTZ NULL DEFAULT NULL,
	"ip" TEXT NULL DEFAULT NULL,
	"user_agent" TEXT NULL DEFAULT NULL,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY ("id"),
	UNIQUE ("token_hash"),
	CONSTRAINT "user_sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX idx_user_sessions_user ON public.user_sessions USING btree (user_id);
CREATE INDEX idx_user_sessions_token ON public.user_sessions USING btree (token_hash);
CREATE INDEX idx_user_sessions_expires ON public.user_sessions USING btree (expires_at);

